mapper.update:
UPDATE product
SET stock = stock + #{quantity}
WHERE id = #{productId}
  AND #{quantity} > 0

UPDATE product
SET stock = stock - #{quantity}
WHERE id = #{productId}
  AND status = 1
  AND is_deleted = 0
  AND price IS NOT NULL
  AND price >= 0
  AND #{quantity} > 0
  AND stock >= #{quantity}

mapper.select:
SELECT id, name, cover_image_url, price, sales_count FROM product WHERE status = 1 AND is_deleted = 0
AND category_id = #{categoryId}
ORDER BY sales_count DESC, id ASC LIMIT #{limit}
